window.CONTENT={"startDate":null,"finalDate":"2026-11-03T00:00:00+03:00","photos":[{"src":"assets/photos/26c05d8caef487.webp","thumb":"assets/photos/26c05d8caef487-thumb.webp","width":1200,"height":1600,"date":"2023-10-08","caption":"Yüzlerimiz küçücük bir kadraja sığmış; sana olan sevgimse hiçbir fotoğrafa sığmayacak kadar büyük."},{"src":"assets/photos/8c6d14392e56d6.webp","thumb":"assets/photos/8c6d14392e56d6-thumb.webp","width":1500,"height":2000,"date":"2023-10-08","caption":"O yeşil ışıkların altında sana bakınca anlıyorum: bir yere alışmam için yanımda senin olman yetiyor."},{"src":"assets/photos/4b209e9ee54b99.webp","thumb":"assets/photos/4b209e9ee54b99-thumb.webp","width":1536,"height":2048,"date":"2023-10-08","caption":"Saçımdaki çiçek biraz komik olabilir; ama senin bir gülüşün için daha neler yaparım, sevgilim."},{"src":"assets/photos/a4903f71502d08.webp","thumb":"assets/photos/a4903f71502d08-thumb.webp","width":1536,"height":2048,"date":"2023-10-08","caption":"Senin gözünden görünen bu adamı seviyorum; çünkü en çok senin hayatındaki yerimi seviyorum."},{"src":"assets/photos/c8ea25bf767b90.webp","thumb":"assets/photos/c8ea25bf767b90-thumb.webp","width":1600,"height":1204,"date":"2023-10-16","caption":"Masada karşıma oturduğunda, sana anlatacaklarımdan önce yüzüne bakıp biraz susmak istiyorum."},{"src":"assets/photos/0fd4cb8d74aafa.webp","thumb":"assets/photos/0fd4cb8d74aafa-thumb.webp","width":4623,"height":3460,"date":"2023-10-21","caption":"Mavinin içinde gülümsüyorsun; suyun ardındaki bütün renklerden daha çok, senin gözlerindeki hayatı seviyorum."},{"src":"assets/photos/a0d7c070b42d5b.webp","thumb":"assets/photos/a0d7c070b42d5b-thumb.webp","width":4623,"height":3460,"date":"2023-10-21","caption":"Başını bana yaklaştırışını kalbimde ayrı bir yere koydum; senin küçük hareketlerin bende büyük bir sevgi bırakıyor."},{"src":"assets/photos/9ccde4452850a3.webp","thumb":"assets/photos/9ccde4452850a3-thumb.webp","width":2000,"height":1500,"date":"2023-11-03","caption":"Arkamızdaki koca şehirden daha çok, yanı başımdaki seninle ilgileniyorum; benim dönmek istediğim yer sensin."},{"src":"assets/photos/94c35748e7e080.webp","thumb":"assets/photos/94c35748e7e080-thumb.webp","width":4623,"height":3460,"date":"2023-11-03","caption":"Birbirimize yaslandığımız bu kare, kalbimin senden yana eğilişinin en güzel resmi."},{"src":"assets/photos/5773bba9e1e820.webp","thumb":"assets/photos/5773bba9e1e820-thumb.webp","width":3460,"height":4623,"date":"2023-11-03","caption":"Sen önde, ben arkandayım; hayatın hangi tarafında durursak duralım, sana yakın kalmayı istiyorum."},{"src":"assets/photos/71edfeeb7d2013.webp","thumb":"assets/photos/71edfeeb7d2013-thumb.webp","width":3460,"height":4623,"date":"2023-11-24","caption":"Yüzün bu kadar yakınımdayken, sana söyleyeceğim en dürüst şey şu: ben bu mesafe hiç büyümesin istiyorum."},{"src":"assets/photos/8bbf4a900b8790.webp","thumb":"assets/photos/8bbf4a900b8790-thumb.webp","width":1200,"height":1600,"date":"2023-11-29","caption":"Loş ışıkta bile gülüşünü seçebiliyorum; seni sevmenin en güzel yanı, gözlerimin hep seni bulması."},{"src":"assets/photos/e0013e64c15d73.webp","thumb":"assets/photos/e0013e64c15d73-thumb.webp","width":1200,"height":1600,"date":"2023-12-17","caption":"Tek başıma olduğum bu kareye sana ait bir cümle bırakayım: keşke baktığım her yeri beraber görsek."},{"src":"assets/photos/552de0cdde59e8.webp","thumb":"assets/photos/552de0cdde59e8-thumb.webp","width":5120,"height":2304,"date":"2023-12-31","caption":"Sana sokulmuş hâlime bakınca, kendimi en çok hangi yerde sevdiğimi görüyorum: senin yanında."},{"src":"assets/photos/aa8c8c7f24aed4.webp","thumb":"assets/photos/aa8c8c7f24aed4-thumb.webp","width":5120,"height":2304,"date":"2024-01-26","caption":"Soğuk renkli bu karede başını bana yaslamışsın; içimi ısıtan şeyin bir mevsim değil sen olduğunu biliyorum."},{"src":"assets/photos/5cb95ce7d69e7d.webp","thumb":"assets/photos/5cb95ce7d69e7d-thumb.webp","width":1440,"height":1440,"date":"2024-02-03","caption":"Beni en sıradan hâlimle bile tanımanı seviyorum; sana âşık olmak, yanında hiçbir rol yapmadan durabilmek de demek."},{"src":"assets/photos/baf1d45ad6c77f.webp","thumb":"assets/photos/baf1d45ad6c77f-thumb.webp","width":5120,"height":2304,"date":"2024-02-25","caption":"Sana yaklaştıkça yüzümde beliren gülüşü seviyorum; kalbimin seni tanıdığı yüzümden belli oluyor."},{"src":"assets/photos/e99982b7d49555.webp","thumb":"assets/photos/e99982b7d49555-thumb.webp","width":5120,"height":2880,"date":"2024-04-10","caption":"Sana verdiğim bu öpücükte, kelimelerle yetişemediğim bütün sevgim var."},{"src":"assets/photos/b78886b68e1adf.webp","thumb":"assets/photos/b78886b68e1adf-thumb.webp","width":1872,"height":4160,"date":"2024-04-12","caption":"Renkli duvarın önünde küçücük görünmüşüz; ama beraber olduğumuzda hayat benim için biraz daha renkleniyor."},{"src":"assets/photos/4f80c5fd828d33.webp","thumb":"assets/photos/4f80c5fd828d33-thumb.webp","width":900,"height":1600,"date":"2024-05-03","caption":"Omuzlarımızın birbirine değdiği bu küçücük yerde, sana ne kadar yakın olmak istediğimi hissediyorum."},{"src":"assets/photos/688190c8d1ee40.webp","thumb":"assets/photos/688190c8d1ee40-thumb.webp","width":1600,"height":1200,"date":"2024-05-03","caption":"Saçların yüzüne, yüzün bana yaklaşmış; sana bakarken fotoğraf çekildiğini bile unutmak isterdim."},{"src":"assets/photos/4c2be953ae7bbf.webp","thumb":"assets/photos/4c2be953ae7bbf-thumb.webp","width":1920,"height":1080,"date":"2024-05-04","caption":"Seninle aynı masada oturmak bile kalbime iyi geliyor; sıradan bir günü seninle güzel yapmayı seviyorum."},{"src":"assets/photos/4e67e282c279cb.webp","thumb":"assets/photos/4e67e282c279cb-thumb.webp","width":5120,"height":2880,"date":"2024-05-05","caption":"Güneş ikimizin de yüzüne vurmuş; sen yanıma yaklaşınca bu fotoğraf benim için bir yazdan daha sıcak oluyor."},{"src":"assets/photos/cb9acd444cc0a2.webp","thumb":"assets/photos/cb9acd444cc0a2-thumb.webp","width":5120,"height":2880,"date":"2024-05-15","caption":"Başını omzuma bırakışın bana çok şey anlatıyor; sana en çok, burada güvende hissetmeni sağlayacak kadar yakın olmak istiyorum."},{"src":"assets/photos/9195190fc84330.webp","thumb":"assets/photos/9195190fc84330-thumb.webp","width":4000,"height":1800,"date":"2024-06-06","caption":"Aynada kendimi seninle beraber görmek hoşuma gidiyor; geleceğe baktığımda da yan yana olduğumuz bir biz görmek istiyorum."},{"src":"assets/photos/e04cb124cb3768.webp","thumb":"assets/photos/e04cb124cb3768-thumb.webp","width":5120,"height":2880,"date":"2024-07-07","caption":"Kucağındaki o küçük yeşil arkadaşla gülümsüyorsun; senin neşeni paylaşmak, sana âşık olmanın en tatlı taraflarından biri."},{"src":"assets/photos/6c014e17d24adc.webp","thumb":"assets/photos/6c014e17d24adc-thumb.webp","width":2880,"height":5120,"date":"2024-07-07","caption":"Işık az, yüzlerimiz birbirine dönük; dünyayı biraz kapatıp yalnızca seninle kalmak istiyorum."},{"src":"assets/photos/fe0ef1353f8a62.webp","thumb":"assets/photos/fe0ef1353f8a62-thumb.webp","width":2880,"height":5120,"date":"2024-07-09","caption":"Yüzünü bana yaklaştırdığın o küçücük anı sakladım; çünkü senin yakınlığın, günümün en sevdiğim kısmı olabiliyor."},{"src":"assets/photos/d578586846e976.webp","thumb":"assets/photos/d578586846e976-thumb.webp","width":688,"height":1416,"date":"2024-07-12","caption":"Kayaların üzerinde yan yana durduğumuz bu karede, benim tutunmak istediğim tek şey senin elin."},{"src":"assets/photos/82332393f8bf0b.webp","thumb":"assets/photos/82332393f8bf0b-thumb.webp","width":2592,"height":4608,"date":"2024-07-13","caption":"Boydan bir fotoğrafa yan yana sığmışız; ben aslında bütün hayatıma seni böyle yakınımda sığdırmak istiyorum."},{"src":"assets/photos/bd80791d181409.webp","thumb":"assets/photos/bd80791d181409-thumb.webp","width":5120,"height":2880,"date":"2024-08-08","caption":"Başını bana yaklaştırdığın bu sıcak renkli karede, seni bir kez daha sevdiğimi fark ediyorum."},{"src":"assets/photos/c9be036e0d5bcc.webp","thumb":"assets/photos/c9be036e0d5bcc-thumb.webp","width":4899,"height":3266,"date":"2024-08-09","caption":"Bir masada sana yer açmak kolay; kalbimdeki yerinse çoktan sana ait, sevgilim."},{"src":"assets/photos/973dd850caadf2.webp","thumb":"assets/photos/973dd850caadf2-thumb.webp","width":4608,"height":2592,"date":"2024-08-10","caption":"Denizin yanında sana sarıldığım bu kareye her baktığımda, içimin neden senin yanında sakinleştiğini yeniden anlıyorum."},{"src":"assets/photos/d705d90ceb606c.webp","thumb":"assets/photos/d705d90ceb606c-thumb.webp","width":4608,"height":2592,"date":"2024-08-10","caption":"Bu fotoğrafta yalnız görünsem de, sevdiğin adam olma düşüncesi bana hep seni hatırlatıyor."},{"src":"assets/photos/e79d352790022e.webp","thumb":"assets/photos/e79d352790022e-thumb.webp","width":4608,"height":2592,"date":"2024-08-10","caption":"Güneş yüzüne vurmuş ama ben bu yazdan en çok senin gülüşünü kalbimde saklamak istiyorum."},{"src":"assets/photos/1423d1ed1ac77a.webp","thumb":"assets/photos/1423d1ed1ac77a-thumb.webp","width":4608,"height":2592,"date":"2024-08-15","caption":"Kollarımın arasındayken gülümseyişini seviyorum; sana sarıldığım yerde dünyadan başka bir şey istemiyorum."},{"src":"assets/photos/2720b950366e79.webp","thumb":"assets/photos/2720b950366e79-thumb.webp","width":1600,"height":900,"date":"2024-08-18","caption":"Gözlerini kapattığın bu sakin anda sana bakıp, huzurunu hiç incitmeden sevmek istiyorum."},{"src":"assets/photos/2f25f310c4d003.webp","thumb":"assets/photos/2f25f310c4d003-thumb.webp","width":1600,"height":1200,"date":"2024-12-15","caption":"Arkamızdaki manzarayı hatırlamasam da olur; yanımda dururken bana hissettirdiklerini unutmak istemiyorum."},{"src":"assets/photos/c0ca074a5bea76.webp","thumb":"assets/photos/c0ca074a5bea76-thumb.webp","width":3266,"height":4898,"date":"2025-01-01","caption":"Yeni bir yılın fotoğrafında bana böyle yaklaşmışsın; ben bütün yıllarımda bu yakınlığın devamını istiyorum."},{"src":"assets/photos/52a7886b701363.webp","thumb":"assets/photos/52a7886b701363-thumb.webp","width":5120,"height":2880,"date":"2025-01-01","caption":"Yeni yılın ışıkları arkamızda kalsın; benim her yeni başlangıçta istediğim şey, elinin elimde olması."},{"src":"assets/photos/693fbb0237423a.webp","thumb":"assets/photos/693fbb0237423a-thumb.webp","width":900,"height":1600,"date":"2025-03-16","caption":"Senin yanında rahatça kendim olabildiğim için seni bir kez daha seviyorum; yanındayken saklayacak bir hâlim kalmıyor."},{"src":"assets/photos/27c0ec3de40755.webp","thumb":"assets/photos/27c0ec3de40755-thumb.webp","width":3520,"height":1980,"date":"2025-03-30","caption":"Bu masada eksik olan tek şey karşımdaki senmişsin gibi geliyor; sana ayırdığım yer hep hazır."},{"src":"assets/photos/81c3539d2e2e0d.webp","thumb":"assets/photos/81c3539d2e2e0d-thumb.webp","width":1200,"height":1600,"date":"2025-04-01","caption":"Elimdeki çiçekler solabilir ama sana baktığımda içimde açılan o güzel şey kalsın istiyorum."},{"src":"assets/photos/be821fa4dbd4b8.webp","thumb":"assets/photos/be821fa4dbd4b8-thumb.webp","width":1200,"height":1600,"date":"2025-04-02","caption":"Saçlarının arasından bana gülümseyen yüzünü öyle seviyorum ki, bu fotoğrafa her baktığımda sana yaklaşasım geliyor."},{"src":"assets/photos/5a18f85ee5b3b4.webp","thumb":"assets/photos/5a18f85ee5b3b4-thumb.webp","width":1200,"height":1600,"date":"2025-04-03","caption":"Yüzüne düşen ışığı değil, o ışığın içinde sevdiğim seni sakladım; bütün doğal hâllerine âşığım."},{"src":"assets/photos/e35dd7b2963c8a.webp","thumb":"assets/photos/e35dd7b2963c8a-thumb.webp","width":1200,"height":1600,"date":"2025-04-03","caption":"Başımı sana yaklaştırdığım bu anda, söyleyemediğim bütün güzel sözler aramızdaki o küçük mesafede duruyor."},{"src":"assets/photos/e465f2ed4d7160.webp","thumb":"assets/photos/e465f2ed4d7160-thumb.webp","width":1200,"height":1600,"date":"2025-04-03","caption":"Yeşilin içinde seni seyrederken, hayatımda güzelliği fark etmemi sağlayan insanın sen olduğunu düşünüyorum."},{"src":"assets/photos/a2f4a05052b753.webp","thumb":"assets/photos/a2f4a05052b753-thumb.webp","width":4000,"height":3000,"date":"2025-05-17","caption":"Başını bana yaslamışsın; keşke seni yoran her günün sonunda omzum böyle hazır olsa."},{"src":"assets/photos/e5a0f127d59a52.webp","thumb":"assets/photos/e5a0f127d59a52-thumb.webp","width":3000,"height":4000,"date":"2025-05-17","caption":"Bu fotoğrafta tek başınasın ama sana bakan gözlerim dolu dolu; varlığını sevmek için yanımda olman bile gerekmiyor."},{"src":"assets/photos/43b5328a3a05df.webp","thumb":"assets/photos/43b5328a3a05df-thumb.webp","width":2304,"height":5120,"date":"2025-06-24","caption":"Gökyüzünün altında yüzlerimiz birbirine yakın; seninle paylaştığım bu küçücük yer bana kocaman bir dünya geliyor."},{"src":"assets/photos/37a54be4746c6a.webp","thumb":"assets/photos/37a54be4746c6a-thumb.webp","width":5120,"height":2304,"date":"2025-06-24","caption":"Kameraya beraber gülümsüyoruz; seni sevmek, mutluluğun bazen yalnızca yanı başımdaki yüz olduğunu bilmek."},{"src":"assets/photos/286b60f3c47948.webp","thumb":"assets/photos/286b60f3c47948-thumb.webp","width":3000,"height":4000,"date":"2025-07-20","caption":"Kameraya değil birbirimize dönmüşüz; seni sevdiğimi bazen en iyi, gözlerimi senden alamayınca anlatıyorum."},{"src":"assets/photos/75aa7046062022.webp","thumb":"assets/photos/75aa7046062022-thumb.webp","width":5120,"height":2304,"date":"2025-07-22","caption":"Gözlüklerin ardında gözlerim yine seni buluyor; sana bakmanın hiçbir bahanesi eskimiyor."},{"src":"assets/photos/b953d77aa928b0.webp","thumb":"assets/photos/b953d77aa928b0-thumb.webp","width":5120,"height":2304,"date":"2025-07-31","caption":"Gün ışığında gülüşün yüzüme de yansımış; bana fark etmeden verdiğin mutluluğu bu karede görüyorum."},{"src":"assets/photos/ff2e9eec90b99c.webp","thumb":"assets/photos/ff2e9eec90b99c-thumb.webp","width":4480,"height":2016,"date":"2025-08-18","caption":"Bu sayfada yalnızca sen varsın; iyi ki hayatımda seni böyle uzun uzun sevebileceğim bir yer var."},{"src":"assets/photos/4c11ee7ff587a6.webp","thumb":"assets/photos/4c11ee7ff587a6-thumb.webp","width":1500,"height":2000,"date":"2025-08-25","caption":"Kırmızı ışıkların içinde yüzünü yanıma getirmişsin; sana yaklaşınca içimin neden böyle ısındığını seviyorum."},{"src":"assets/photos/4cd228a51a6712.webp","thumb":"assets/photos/4cd228a51a6712-thumb.webp","width":2048,"height":1536,"date":"2025-08-25","caption":"Bu masadaki sıradan hâlimi seninle paylaşmak istiyorum; büyük anlar kadar küçük günlerimde de sen ol."},{"src":"assets/photos/b84bc2c9519046.webp","thumb":"assets/photos/b84bc2c9519046-thumb.webp","width":1500,"height":2000,"date":"2025-08-25","caption":"Gece ışığı saçlarına değmiş; ben en çok parmaklarımı o saçların arasından geçirip sana sarılmak istiyorum."},{"src":"assets/photos/4a734cdac9e09f.webp","thumb":"assets/photos/4a734cdac9e09f-thumb.webp","width":2160,"height":2880,"date":"2025-08-25","caption":"Yanında durduğum bu kareye en içten sözümü bırakıyorum: sana yakın olmak hâlâ içimi kıpır kıpır ediyor."},{"src":"assets/photos/a2d7a841509426.webp","thumb":"assets/photos/a2d7a841509426-thumb.webp","width":1872,"height":4160,"date":"2025-08-26","caption":"Elindeki çantanla kameraya dönmüşsün; ben senin en doğal hâlini bile gözlerimi alamadan sevebiliyorum."},{"src":"assets/photos/52178f4c22869b.webp","thumb":"assets/photos/52178f4c22869b-thumb.webp","width":4480,"height":2016,"date":"2025-08-26","caption":"Başını eğmişsin, ben yanındayım; konuşmasak bile sana yakınlığımızın içimi doldurmasını seviyorum."},{"src":"assets/photos/c7b70564ed2ecb.webp","thumb":"assets/photos/c7b70564ed2ecb-thumb.webp","width":2048,"height":994,"date":"2025-09-09","caption":"Pembe çiçeklerin arasında seni görünce bütün romantik cümleler aklıma geliyor, ama en doğrusu hâlâ şu: seni seviyorum."},{"src":"assets/photos/31130993dee49a.webp","thumb":"assets/photos/31130993dee49a-thumb.webp","width":1600,"height":1200,"date":"2025-09-29","caption":"Koltukta birbirimize yaslandığımız bu hâlimiz, benim en sevdiğim plan: sana yakın olup hiçbir yere yetişmemek."},{"src":"assets/photos/7f2557438d146f.webp","thumb":"assets/photos/7f2557438d146f-thumb.webp","width":1200,"height":1600,"date":"2025-10-10","caption":"Karanlık bir kareye iki gülüş bırakmışız; benim gecelerimin en güzel tarafı, seninle paylaşabildiklerim."},{"src":"assets/photos/3e9f0f6e1d7a4d.webp","thumb":"assets/photos/3e9f0f6e1d7a4d-thumb.webp","width":5120,"height":2304,"date":"2025-10-10","caption":"Gecenin ışığında birbirimize yaklaşmışız; sevgilim, her kalabalıkta dönüp sana bakacak bir yanım var."},{"src":"assets/photos/e788875ac8495f.webp","thumb":"assets/photos/e788875ac8495f-thumb.webp","width":6944,"height":9248,"date":"2025-10-10","caption":"Bu fotoğrafta sana tek başına bakıyorum ve içimden, seni hayatıma sığdırdığım için ne kadar mutlu olduğumu söylemek geliyor."},{"src":"assets/photos/11a4fd87ac09f1.webp","thumb":"assets/photos/11a4fd87ac09f1-thumb.webp","width":3024,"height":4032,"date":"2025-10-18","caption":"Masada yan yana duruşumuza bakınca, sana yakın olmanın ne kadar küçük ve ne kadar büyük bir mutluluk olduğunu hissediyorum."},{"src":"assets/photos/db5980d0c01183.webp","thumb":"assets/photos/db5980d0c01183-thumb.webp","width":2000,"height":1500,"date":"2025-11-23","caption":"Yüzün yüzüme bu kadar yakınken, seni sevdiğimi söylemek yerine bir kez daha sarılmak istiyorum."},{"src":"assets/photos/2459420d97acd5.webp","thumb":"assets/photos/2459420d97acd5-thumb.webp","width":1536,"height":2048,"date":"2025-12-31","caption":"Elindeki çiçeklere değil sana bakıyorum; çünkü bu fotoğrafta sevdiğim bütün güzellikler sende toplanmış."},{"src":"assets/photos/46c0d60462820b.webp","thumb":"assets/photos/46c0d60462820b-thumb.webp","width":5120,"height":2304,"date":"2025-12-31","caption":"Kameraya biraz, birbirimize daha çok yakınız; kalbimin mesafesi her fotoğrafta senden yana."},{"src":"assets/photos/dee624f14468bf.webp","thumb":"assets/photos/dee624f14468bf-thumb.webp","width":5120,"height":2304,"date":"2025-12-31","caption":"Sana verdiğim bu öpücüğü bir sayfaya sakladım; ama seni sevmeyi bu günlüğün çok ötesinde sürdürmek istiyorum."},{"src":"assets/photos/98f5f3d8bd3685.webp","thumb":"assets/photos/98f5f3d8bd3685-thumb.webp","width":5120,"height":2304,"date":"2026-02-15","caption":"Geceye yan yana bir gülümseme bırakmışız; seninle olduğum anların içimde bıraktığı ışık kolay kolay sönmüyor."},{"src":"assets/photos/9c666acbbdf742.webp","thumb":"assets/photos/9c666acbbdf742-thumb.webp","width":5120,"height":2304,"date":"2026-02-15","caption":"Fotoğraftaki bu öpücük dursun, sevgilim; sana sevgimi yalnızca sözlerle değil, yakınlığımla da anlatmak istiyorum."},{"src":"assets/photos/058a8e7e176d2f.webp","thumb":"assets/photos/058a8e7e176d2f-thumb.webp","width":1080,"height":2400,"date":null,"caption":"Küçücük bir ekran görüntüsünde bile seni görünce kalbim yumuşuyor; bana ait bir günün içinde sana yer açmak çok güzel."},{"src":"assets/photos/1be4ce4d7289b8.webp","thumb":"assets/photos/1be4ce4d7289b8-thumb.webp","width":1080,"height":2400,"date":null,"caption":"Bu sohbet ekranında beni sana bağlayan o küçük şeyleri seviyorum; aynı yerde olmasak da günümde senin bir sesin olsun istiyorum."}],"chapters":[{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]},{"pages":[]}]};
